def parse_scheme_percent(value):
    """Convert a scheme/discount entry to a decimal fraction.
    Accepts values such as 34, 34%, 0.34, or 0.34%.
    For normal user-entered percentage values, 34 means 34%.
    """
    if value is None:
        return 0.0
    text = str(value).strip().replace("%", "")
    if not text:
        return 0.0
    try:
        number = float(text)
    except (TypeError, ValueError):
        return 0.0
    if number > 1:
        return number / 100.0
    # Decimal values between 0 and 1 are already fractions (e.g. 0.34 = 34%).
    return number

def calculate_primary_values(rate, scheme):
    rate = float(rate or 0)
    discount_rate = parse_scheme_percent(scheme)
    discount_amount = round(rate * discount_rate, 2)
    net_price = round(rate - discount_amount, 2)
    return discount_rate, discount_amount, net_price


def ensure_scheme_columns(conn):
    """Create admin-maintained NV scheme tables. Existing data is preserved."""
    conn.execute("""CREATE TABLE IF NOT EXISTS nv_scheme_rules(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        product_id INTEGER NOT NULL UNIQUE,
        trade_promotion REAL NOT NULL DEFAULT 0,
        slab1_percent REAL NOT NULL DEFAULT 0, slab1_cs REAL NOT NULL DEFAULT 0,
        slab2_percent REAL NOT NULL DEFAULT 0, slab2_cs REAL NOT NULL DEFAULT 0,
        slab3_percent REAL NOT NULL DEFAULT 0, slab3_cs REAL NOT NULL DEFAULT 0,
        slab1_text TEXT DEFAULT '', slab2_text TEXT DEFAULT '', slab3_text TEXT DEFAULT '',
        updated_at TEXT NOT NULL,
        FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS nv_scheme_categories(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        category_name TEXT NOT NULL UNIQUE,
        brand TEXT NOT NULL DEFAULT 'ENVY',
        trade_promotion REAL NOT NULL DEFAULT 0,
        slab1_percent REAL NOT NULL DEFAULT 0, slab1_cs REAL NOT NULL DEFAULT 0,
        slab2_percent REAL NOT NULL DEFAULT 0, slab2_cs REAL NOT NULL DEFAULT 0,
        slab3_percent REAL NOT NULL DEFAULT 0, slab3_cs REAL NOT NULL DEFAULT 0,
        slab1_text TEXT DEFAULT '', slab2_text TEXT DEFAULT '', slab3_text TEXT DEFAULT '',
        updated_at TEXT NOT NULL
    )""")
    scheme_cols = {r["name"] for r in conn.execute("PRAGMA table_info(nv_scheme_categories)").fetchall()}
    if "brand" not in scheme_cols:
        conn.execute("ALTER TABLE nv_scheme_categories ADD COLUMN brand TEXT NOT NULL DEFAULT 'ENVY'")

