    nano_now = datetime.now().isoformat(timespec="seconds")
    conn.execute(
        "INSERT OR IGNORE INTO categories(name,description,created_at,updated_at) VALUES(?,?,?,?)",
        ("Nano", "Nano catalogue", nano_now, nano_now)
    )
