def _sync_smr_product_catalog(conn):
    """Sync the 77-product SMR catalogue from SMR_PRODUCT_CATALOG.xlsx."""
    path=os.path.join(BASE_DIR,'SMR_PRODUCT_CATALOG.xlsx')
    if not os.path.exists(path): return
    try:
        wb=load_workbook(path,data_only=True,read_only=True); ws=wb.active
    except Exception:
        return
    current='Uncategorized'; catalog=[]
    for col in range(1,ws.max_column+1):
        mrp=ws.cell(1,col).value; cat=ws.cell(2,col).value; name=ws.cell(3,col).value
        if not name or str(name).strip().upper().startswith('TOTAL'): continue
        if cat is not None and str(cat).strip(): current=' '.join(str(cat).replace('\xa0',' ').split())
        clean_name=' '.join(str(name).replace('\xa0',' ').split())
        try: clean_mrp=float(mrp or 0)
        except (TypeError,ValueError): clean_mrp=0
        catalog.append((col,current,clean_name,clean_mrp))
    wb.close()
    if not catalog: return
    now=datetime.now().isoformat(timespec='seconds')
    # Catalogue sync must never overwrite Admin-managed ACTIVE/INACTIVE status.
    # Existing products keep their current status; new catalogue rows start ACTIVE.
    used_ids=set()
    for col,category,name,mrp in catalog:
        code=f'SMRCAT{col:03d}'
        row=conn.execute('SELECT id FROM products WHERE product_code=?',(code,)).fetchone()
        if row: product_id=int(row['id'])
        else:
            matches=conn.execute('SELECT id FROM products WHERE LOWER(TRIM(name))=LOWER(TRIM(?)) AND mrp=? ORDER BY id',(name,mrp)).fetchall()
            product_id=next((int(m['id']) for m in matches if int(m['id']) not in used_ids),None)
        brand='Pure Home' if name.lower().startswith('pour home') else ('ENVY' if name.lower().startswith('envy') else ('Vanesa' if name.lower().startswith('vanesa') else ('London Glow' if name.lower().startswith('london glow') else '')))
        conn.execute("INSERT INTO categories(name,description,created_at,updated_at) VALUES(?,?,?,?) ON CONFLICT(name) DO UPDATE SET updated_at=excluded.updated_at",
                     (category,'Imported SMR product category',now,now))
        if product_id:
            conn.execute("UPDATE products SET product_code=?,name=?,category=?,brand=?,mrp=?,updated_at=? WHERE id=?",
                         (code,name,category,brand,mrp,now,product_id))
        else:
            cur=conn.execute("""INSERT INTO products(product_code,name,category,brand,flavor,description,gm_ml,mrp,case_size,price,stock,image_url,status,created_at,updated_at)
                                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                             (code,name,category,brand,'',name,'',mrp,0,0,0,'','ACTIVE',now,now))
            product_id=cur.lastrowid
        used_ids.add(int(product_id))
        conn.execute("INSERT INTO depot_stock(product_id,depot_name,quantity,updated_at) VALUES(?,?,?,?) ON CONFLICT(product_id) DO NOTHING",
                     (product_id,'Main Depot',0,now))
        conn.execute("INSERT INTO inventory(product_id,available_quantity,reserved_quantity,reorder_level,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(product_id) DO NOTHING",
                     (product_id,0,0,10,now))
    conn.commit()


def _norm_product_name(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()

def _parse_depot_stock_workbook(path):
    wb=load_workbook(path,data_only=True,read_only=True); ws=wb.active
    rows=list(ws.iter_rows(values_only=True)); wb.close()
    if not rows: raise ValueError("The depot stock Excel file is empty.")
    header_idx=0
    for i,row in enumerate(rows[:12]):
        vals=[str(v or "").strip().casefold() for v in row]
        if any("product" in v and "name" in v for v in vals) and any(any(k in v for k in ("stock","quantity","qty")) for v in vals):
            header_idx=i; break
    headers=[str(v or "").strip().casefold() for v in rows[header_idx]]
    name_idx=next((i for i,v in enumerate(headers) if "product" in v and "name" in v),0)
    qty_idx=next((i for i,v in enumerate(headers) if any(k in v for k in ("stock","quantity","qty")) and "case size" not in v),None)
    if qty_idx is None: raise ValueError("Depot Stock Excel must contain Product Name and Stock/Quantity columns.")
    result={}
    for row in rows[header_idx+1:]:
        if name_idx>=len(row): continue
        name=str(row[name_idx] or "").strip()
        if not name: continue
        try: qty=max(0,int(float(str(row[qty_idx]).replace(",",""))))
        except (TypeError,ValueError): continue
        key=_norm_product_name(name)
        if not key:
            continue
        # A depot file may contain the same product in multiple batches/rows.
        # Treat Product Name as the only key and SUM all quantities for that name.
        if key in result:
            old_name, old_qty = result[key]
            result[key] = (old_name, old_qty + qty)
        else:
            result[key]=(name,qty)
    return list(result.values())

def sync_products_from_depot_rows(conn,stock_rows):
    now=datetime.now().isoformat(timespec="seconds")
    incoming={_norm_product_name(n):(n,max(0,int(q))) for n,q in stock_rows if str(n).strip()}
    conn.execute("UPDATE products SET stock=0,status='INACTIVE',stock_new=0,updated_at=?",(now,))
    conn.execute("UPDATE depot_stock SET quantity=0,updated_at=?",(now,))
    conn.execute("UPDATE inventory SET available_quantity=0,updated_at=?",(now,))
    existing=conn.execute("SELECT * FROM products").fetchall(); by_name={_norm_product_name(r['name']):r for r in existing if _norm_product_name(r['name'])}
    updated_count=new_count=0
    for norm,(name,qty) in incoming.items():
        # Product Name is the ONLY matching key. Existing master names are reused;
        # a genuinely new Excel product keeps its real Excel name and is highlighted.
        p=by_name.get(norm)
        if p:
            conn.execute("UPDATE products SET stock=?,status=?,stock_new=0,updated_at=? WHERE id=?",(qty,"ACTIVE" if qty>0 else "INACTIVE",now,p['id']))
            conn.execute("INSERT INTO depot_stock(product_id,depot_name,quantity,updated_at) VALUES(?,?,?,?) ON CONFLICT(product_id) DO UPDATE SET quantity=excluded.quantity,updated_at=excluded.updated_at",(p['id'],'Main Depot',qty,now))
            conn.execute("INSERT INTO inventory(product_id,available_quantity,reserved_quantity,reorder_level,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(product_id) DO UPDATE SET available_quantity=excluded.available_quantity,updated_at=excluded.updated_at",(p['id'],qty,0,10,now)); updated_count+=1
        else:
            base="DEPOT-"+re.sub(r"[^A-Z0-9]+","",name.upper())[:24] or "DEPOT-NEW"; code=base; n=2
            while conn.execute("SELECT 1 FROM products WHERE product_code=?",(code,)).fetchone(): code=f"{base}-{n}"; n+=1
            conn.execute("INSERT INTO products(product_code,name,category,description,mrp,case_size,price,stock,image_url,status,stock_new,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(code,name,'Imported','Added from Depot Stock Excel',0,0,0,qty,'','ACTIVE' if qty>0 else 'INACTIVE',1,now,now))
            pid=conn.execute("SELECT last_insert_rowid()").fetchone()[0]
            conn.execute("INSERT INTO depot_stock(product_id,depot_name,quantity,updated_at) VALUES(?,?,?,?)",(pid,'Main Depot',qty,now))
            conn.execute("INSERT INTO inventory(product_id,available_quantity,reserved_quantity,reorder_level,updated_at) VALUES(?,?,?,?,?)",(pid,qty,0,10,now)); new_count+=1
    return updated_count,new_count

def normalize_order_status(status):
    value=(status or "PENDING").strip().upper()
    if value in {"COMPLETED","PROCESSING","APPROVED","CONFIRMED"}: return "CONFIRMED"
    if value in {"CANCELLED","REJECTED","CANCELED"}: return "CANCELED"
    return "PENDING"

def sync_primary_order_from_order(conn, order_id):
    order=conn.execute("SELECT order_type, order_number, status FROM orders WHERE id=?",(order_id,)).fetchone()
    if order and order["order_type"]=="PRIMARY ORDER":
        conn.execute("UPDATE primary_orders SET status=? WHERE reference_no=?",(normalize_order_status(order["status"]),order["order_number"]))

def build_order_excel(order_id):
    template_path=os.path.join(BASE_DIR,"SMR SALF.xlsx")
    if not os.path.exists(template_path): raise FileNotFoundError("SMR SALF.xlsx is missing.")
    conn=db()
    order=conn.execute("SELECT o.*,d.dealer_name,d.town,d.sap_code FROM orders o LEFT JOIN dealers d ON d.id=o.dealer_id WHERE o.id=?",(order_id,)).fetchone()
    rows=conn.execute("SELECT oi.*,p.name product_name,p.product_code,p.case_size,p.mrp master_mrp,p.price master_rate FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id",(order_id,)).fetchall() if order else []
    conn.close()
    if not order: raise ValueError("Order not found.")
    from copy import copy
    wb=load_workbook(template_path); ws=wb[wb.sheetnames[0]]; source_wb=load_workbook(template_path); source_ws=source_wb[source_wb.sheetnames[0]]
    for r in range(8,ws.max_row+1):
        for c in range(1,11): ws.cell(r,c).value=None
    ws["A4"]=f"Distributor  Name :- {order['dealer_name'] or ''}"; ws["A5"]=f"Town :-  {order['town'] or ''}"; ws["A6"]=f"Order Date :-  {str(order['order_date'] or '')[:10]}"; ws["I4"]="Invoice Value With Tax"
    for r,item in enumerate(rows,start=8):
        for c in range(1,11): ws.cell(r,c)._style=copy(source_ws.cell(8,c)._style); ws.cell(r,c).number_format=source_ws.cell(8,c).number_format
        mrp=float(item['mrp'] or item['master_mrp'] or item['master_rate'] or 0); rate=float(item['unit_price'] or item['master_rate'] or 0); dr,da,net=calculate_primary_values(rate,item['scheme'] or '0'); pcs=int(item['quantity'] or 0); cs=int(item['case_size'] or 0); cases=round(pcs/cs,4) if cs else 0
        vals=[f"{item['product_name']}"+(f" - {item['product_code']}" if item['product_code'] else ''),cs,f"MRP-{mrp:g}",rate,dr,round(da,2),round(net,2),cases,pcs,round(net*pcs,2)]
        for c,v in enumerate(vals,1): ws.cell(r,c).value=v
        ws.cell(r,4).number_format='0.00'; ws.cell(r,5).number_format='0%'; ws.cell(r,6).number_format='0.00'; ws.cell(r,7).number_format='0.00'; ws.cell(r,10).number_format='0.00'
    last=7+len(rows); total=last+1
    for tr,sr in zip((total,total+1,total+2),(98,99,100)):
        for c in range(1,11): ws.cell(tr,c)._style=copy(source_ws.cell(sr,c)._style); ws.cell(tr,c).number_format=source_ws.cell(sr,c).number_format
        ws.row_dimensions[tr].height=source_ws.row_dimensions[sr].height
    ws.cell(total,1).value='Total Amount Without Tax'; ws.cell(total,10).value=f'=SUM(J8:J{last})' if rows else 0
    ws.cell(total+1,1).value='GST'; ws.cell(total+1,10).value=f'=J{total}*18/100'
    ws.cell(total+2,1).value='Total Bill Amount'; ws.cell(total+2,8).value=f'=SUM(H8:H{last})' if rows else 0; ws.cell(total+2,9).value=f'=SUM(I8:I{last})' if rows else 0; ws.cell(total+2,10).value=f'=J{total}+J{total+1}'; ws['I5']=f'=J{total+2}'
    ws.auto_filter.ref=f'A7:J{last if rows else 7}'; ws.print_area=f'A1:J{total+2}'; ws.freeze_panes='A8'
    if ws.max_row>=total+3: ws.delete_rows(total+3,ws.max_row-total-2)
    source_wb.close(); bio=io.BytesIO(); wb.save(bio); bio.seek(0); return bio

def login_required():
    return "user_id" in session

def admin_required():
    return session.get("role") == "ADMIN"

_user_activation_schema_ready = False
_tsst_schema_ready = False


def _ensure_user_activation_schema(conn):
    global _user_activation_schema_ready
    if _user_activation_schema_ready:
        return
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS can_edit_products BOOLEAN NOT NULL DEFAULT FALSE")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS can_view_reports BOOLEAN NOT NULL DEFAULT FALSE")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS tsst_designation TEXT NOT NULL DEFAULT ''")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS headquarters TEXT NOT NULL DEFAULT ''")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS mobile_number TEXT NOT NULL DEFAULT ''")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS division TEXT NOT NULL DEFAULT ''")
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS reporting_superior TEXT NOT NULL DEFAULT ''")
    conn.commit()
    _user_activation_schema_ready = True


def _ensure_dealer_contact_schema(conn):
    conn.execute("ALTER TABLE dealers ADD COLUMN IF NOT EXISTS contact_number TEXT NOT NULL DEFAULT ''")
    conn.execute("ALTER TABLE dealers ADD COLUMN IF NOT EXISTS address TEXT NOT NULL DEFAULT ''")
    conn.commit()


def _ensure_tsst_schema(conn):
    global _tsst_schema_ready
    if _tsst_schema_ready:
        return
    conn.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS tsst_designation TEXT NOT NULL DEFAULT ''")
    conn.execute("""CREATE TABLE IF NOT EXISTS monthly_targets(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        user_id INTEGER NOT NULL,
        year INTEGER NOT NULL,
        month INTEGER NOT NULL,
        target_amount REAL NOT NULL DEFAULT 0,
        UNIQUE(user_id,year,month),
        FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS dealer_targets(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        dealer_name TEXT NOT NULL,
        sap_code TEXT,
        target_amount REAL NOT NULL DEFAULT 0,
        achieved_amount REAL NOT NULL DEFAULT 0,
        month_year TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS tsst_management_records(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        employee_name TEXT NOT NULL,
        emp_code TEXT,
        metric_name TEXT,
        score REAL NOT NULL DEFAULT 0,
        metric_date TEXT
    )""")
    conn.commit()
    _tsst_schema_ready = True


def _manager_has_permission(permission):
    if permission not in {"can_edit_products", "can_view_reports"}:
        raise ValueError("Unknown manager permission.")
    user_id = session.get("user_id")
    if not user_id or session.get("role") != "MANAGER":
        return False
    conn = db()
    try:
        _ensure_user_activation_schema(conn)
        user = conn.execute(
            f"SELECT {permission} FROM users WHERE id=? AND role='MANAGER' AND is_active=TRUE",
            (user_id,)
        ).fetchone()
        return bool(user and user[permission])
    finally:
        conn.close()


def _product_edit_access_response():
    if not login_required():
        return redirect(url_for("login"))
    if admin_required() or _manager_has_permission("can_edit_products"):
        return None
    abort(403)


def _report_access_response():
    if not login_required():
        return redirect(url_for("login"))
    if admin_required() or _manager_has_permission("can_view_reports"):
        return None
    abort(403)


def _admin_access_response():
    if not login_required():
        return redirect(url_for("login"))
    if not admin_required():
        abort(403)
    return None


def _validated_product_payload(form_data):
    """Normalize a product form payload and reject invalid numeric fields."""
    product_code = (form_data.get("product_code", "") or "").strip()
    name = (form_data.get("name", "") or "").strip()
    if not product_code or not name:
        raise ValueError("Product code and product name are required.")

    status = (form_data.get("status", "ACTIVE") or "ACTIVE").upper()
    if status not in {"ACTIVE", "INACTIVE"}:
        raise ValueError("Product status must be ACTIVE or INACTIVE.")

    def parse_float(field_name, default=0.0):
        raw = form_data.get(field_name, default)
        if raw is None or str(raw).strip() == "":
            return float(default)
        try:
            value = float(raw)
        except (TypeError, ValueError):
            raise ValueError(f"{field_name.upper()} must be a valid number.") from None
        if value < 0:
            raise ValueError(f"{field_name.upper()} cannot be negative.")
        return value

    def parse_int(field_name, default=0):
        raw = form_data.get(field_name, default)
        if raw is None or str(raw).strip() == "":
            return int(default)
        try:
            value = int(float(raw))
        except (TypeError, ValueError):
            raise ValueError(f"{field_name.upper()} must be a valid whole number.") from None
        if value < 0:
            raise ValueError(f"{field_name.upper()} cannot be negative.")
        return value

    data = {
        "product_code": product_code,
        "name": name,
        "category": (form_data.get("category", "") or "").strip(),
        "description": (form_data.get("description", "") or "").strip(),
        "mrp": parse_float("mrp"),
        "price": parse_float("price"),
        "stock": parse_int("stock"),
        "image_url": (form_data.get("image_url", "") or "").strip(),
        "status": status,
    }
    return data

@app.context_processor
def inject_globals():
    context = {
        "logged_user": session.get("name"),
        "role": session.get("role"),
        "can_edit_products": bool(session.get("can_edit_products")),
        "can_view_reports": bool(session.get("can_view_reports")),
        "pending_orders_count": 0,
        "pending_orders": [],
    }
    if session.get("role") == "ADMIN":
        conn = db()
        try:
            pending_status = """UPPER(COALESCE(status,'PENDING')) NOT IN
                ('COMPLETED','PROCESSING','APPROVED','CONFIRMED','CANCELLED','CANCELED','REJECTED')"""
            context["pending_orders_count"] = conn.execute(
                f"SELECT COUNT(*) AS c FROM orders WHERE {pending_status}"
            ).fetchone()["c"]
            context["pending_orders"] = conn.execute(
                f"""SELECT o.id,o.order_number,o.status,o.total_amount,
                           u.name AS customer_name,
                           CASE WHEN NULLIF(CAST(o.billing_date AS TEXT),'') IS NOT NULL
                                THEN CAST(o.billing_date AS DATE)
                                ELSE CAST(o.order_date AS TIMESTAMP)::date END AS display_date
                    FROM orders o
                    JOIN users u ON u.id=o.user_id
                    WHERE {pending_status.replace('status', 'o.status')}
                    ORDER BY o.id DESC
                    LIMIT 10"""
            ).fetchall()
        finally:
            conn.close()
    return context

def _dashboard_scope(conn):
    """Return dealers visible to the logged-in user/admin."""
    if session.get("role") == "ADMIN":
        return conn.execute("SELECT * FROM dealers WHERE active=1 ORDER BY dealer_name").fetchall()
    user = conn.execute("SELECT id,name,user_code FROM users WHERE id=?", (session.get("user_id"),)).fetchone()
    if not user:
        return []
    return conn.execute(
        "SELECT * FROM dealers WHERE active=1 AND (emp_code=? OR emp_name=?) ORDER BY dealer_name",
        (user["user_code"] or "", user["name"] or "")
    ).fetchall()

def _month_bounds(year, month):
    from calendar import monthrange
    return f"{year:04d}-{month:02d}-01", f"{year:04d}-{month:02d}-{monthrange(year, month)[1]:02d}"

def _product_target_metrics(conn, year, month):
    """Return monthly product targets and sales-based progress."""
    targets = conn.execute(
        "SELECT id, category, target_pieces FROM product_targets WHERE year=? AND month=? ORDER BY id",
        (year, month)
    ).fetchall()
    if not targets:
        return []

    start_date, end_date = _month_bounds(year, month)
    scope_sql = ""
    scope_params = []
    if session.get("role") != "ADMIN":
        scope_sql = " AND o.user_id=?"
        scope_params.append(session.get("user_id"))

    result = []
    target_match_sql = {
        "ENVY DEO": "(UPPER(COALESCE(p.brand,''))='ENVY' AND (LOWER(COALESCE(p.name,'')) LIKE '%deo%' OR LOWER(COALESCE(p.category,'')) LIKE '%deo%'))",
        "NANO": "(LOWER(COALESCE(p.category,''))='nano' OR LOWER(COALESCE(p.name,'')) LIKE '%nano%')",
        "Perfumes (60ML)": "(UPPER(COALESCE(p.brand,''))='ENVY' AND LOWER(COALESCE(p.category,''))='perfume' AND LOWER(COALESCE(p.gm_ml,'')) LIKE '%60ml%')",
        "Perfumes (30ML)": "(UPPER(COALESCE(p.brand,''))='ENVY' AND LOWER(COALESCE(p.category,''))='perfume' AND LOWER(COALESCE(p.gm_ml,'')) LIKE '%30ml%')",
        "PH RF": "(UPPER(COALESCE(p.brand,''))='PURE HOME' AND LOWER(COALESCE(p.category,''))='room freshener 126gm/220ml')",
        "PH RF 250 ML": "(UPPER(COALESCE(p.brand,''))='PURE HOME' AND LOWER(COALESCE(p.category,''))='room freshener 250ml')",
        "Nector": "(LOWER(COALESCE(p.category,''))='room freshener nector' OR LOWER(COALESCE(p.name,'')) LIKE '%nector%')",
        "Pour Home Air Freshner 50g": "(LOWER(COALESCE(p.category,'')) LIKE '%air freshner blocks%' OR LOWER(COALESCE(p.name,'')) LIKE '%air freshner%')",
        "Pour Home NEO Gel 7.5GM": "(LOWER(COALESCE(p.category,''))='pour home neo gel' AND LOWER(COALESCE(p.gm_ml,'')) LIKE '%7.5gm%')",
    }

    for target in targets:
        category = str(target["category"]).strip()
        match_sql = target_match_sql.get(category, "LOWER(TRIM(COALESCE(p.category,''))) = LOWER(TRIM(?))")
        extra_params = [] if category in target_match_sql else [category]
        row = conn.execute(
            f"""SELECT COALESCE(SUM(oi.quantity),0) achieved
                FROM order_items oi
                JOIN orders o ON o.id=oi.order_id
                JOIN products p ON p.id=oi.product_id
                WHERE o.status IN ('CONFIRMED','COMPLETED')
                  AND CAST(o.order_date AS TIMESTAMP)::date BETWEEN ?::date AND ?::date
                  AND {match_sql}
                  {scope_sql}""",
            tuple([start_date, end_date, *extra_params, *scope_params])
        ).fetchone()
        achieved = int(row["achieved"] or 0)
        target_pieces = int(target["target_pieces"] or 0)
        remaining = max(0, target_pieces - achieved)
        achieved_pct = (achieved / target_pieces * 100) if target_pieces else 0.0
        result.append({
            "category": target["category"],
            "target": target_pieces,
            "achieved": achieved,
            "remaining": remaining,
            "achieved_pct": achieved_pct,
        })

    from calendar import monthrange
    today = datetime.now()
    if today.year == year and today.month == month:
        days_remaining = max(1, monthrange(year, month)[1] - today.day + 1)
    elif (year, month) > (today.year, today.month):
        days_remaining = monthrange(year, month)[1]
    else:
        days_remaining = 0
    for row in result:
        row["req_per_day"] = (row["remaining"] / days_remaining) if days_remaining else 0.0
    return result


@app.route("/admin/product-targets", methods=["GET", "POST"])
def admin_product_targets():
    if not admin_required():
        return redirect(url_for("admin_login"))

    year = request.values.get("year", type=int) or datetime.now().year
    month = request.values.get("month", type=int) or datetime.now().month
    month = max(1, min(12, month))

    conn = db()
    try:
        _ensure_user_activation_schema(conn)
        if request.method == "POST":
            categories = request.form.getlist("category")
            values = request.form.getlist("target_pieces")
            deleted = set(request.form.getlist("delete_category"))

            for category, value in zip(categories, values):
                category = category.strip()
                if not category or category in deleted:
                    continue
                try:
                    target_pieces = max(0, int(value or 0))
                except (TypeError, ValueError):
                    target_pieces = 0
                conn.execute(
                    "INSERT INTO product_targets(year,month,category,target_pieces) VALUES(?,?,?,?) "
                    "ON CONFLICT(year,month,category) DO UPDATE SET target_pieces=EXCLUDED.target_pieces",
                    (year, month, category, target_pieces)
                )

            for category in deleted:
                conn.execute("DELETE FROM product_targets WHERE year=? AND month=? AND category=?", (year, month, category))

            new_category = request.form.get("new_category", "").strip()
            new_value = request.form.get("new_target_pieces", "").strip()
            if new_category:
                try:
                    new_target = max(0, int(new_value or 0))
                except (TypeError, ValueError):
                    new_target = 0
                conn.execute(
                    "INSERT INTO product_targets(year,month,category,target_pieces) VALUES(?,?,?,?) "
                    "ON CONFLICT(year,month,category) DO UPDATE SET target_pieces=EXCLUDED.target_pieces",
                    (year, month, new_category, new_target)
                )

            conn.commit()
            flash(f"Product targets saved for {datetime(year, month, 1).strftime('%B %Y')}.", "success")
            return redirect(url_for("admin_product_targets", year=year, month=month))

        rows = conn.execute(
            "SELECT category,target_pieces FROM product_targets WHERE year=? AND month=? ORDER BY id",
            (year, month)
        ).fetchall()
        total_target = sum(int(r["target_pieces"] or 0) for r in rows)
        _ensure_monthly_product_targets_table(conn)
        month_year = f"{year:04d}-{month:02d}"
        monthly_targets = conn.execute(
            """SELECT mpt.user_id,mpt.product_id,mpt.target_qty,u.name AS user_name,
                      p.name AS product_name,p.product_code
               FROM monthly_product_targets mpt
               JOIN users u ON u.id=mpt.user_id
               JOIN products p ON p.id=mpt.product_id
               WHERE mpt.month_year=?
               ORDER BY u.name,p.name""",
            (month_year,)
        ).fetchall()
        target_users = conn.execute(
            "SELECT id,name,user_code FROM users WHERE role='USER' AND is_active=TRUE ORDER BY name"
        ).fetchall()
        target_products = conn.execute(
            "SELECT id,name,product_code FROM products WHERE status='ACTIVE' ORDER BY name"
        ).fetchall()
        return render_template(
            "admin/product_targets.html", rows=rows, year=year, month=month,
            total_target=total_target, month_year=month_year,
            monthly_targets=monthly_targets, target_users=target_users,
            target_products=target_products
        )
    finally:
        conn.close()


def _save_dealer_targets_bulk(conn, month_year, form):
    dealer_ids = form.getlist("dealer_id[]")
    target_values = form.getlist("target_amount[]")
    achievement_values = form.getlist("achievement_amount[]")
    saved_count = 0
    for index, raw_dealer_id in enumerate(dealer_ids):
        try:
            dealer_id = int(raw_dealer_id)
            target_amount = float(target_values[index] if index < len(target_values) else 0)
            achieved_amount = float(achievement_values[index] if index < len(achievement_values) else 0)
        except (TypeError, ValueError, IndexError):
            raise ValueError("All target and achievement amounts must be valid numbers.")
        if (
            dealer_id < 1
            or not math.isfinite(target_amount) or target_amount < 0
            or not math.isfinite(achieved_amount) or achieved_amount < 0
        ):
            raise ValueError("Dealer records and amounts must be valid non-negative values.")

        dealer = conn.execute(
            "SELECT id,dealer_name,sap_code FROM dealers WHERE id=? AND active=1",
            (dealer_id,),
        ).fetchone()
        if not dealer:
            raise ValueError(f"Dealer ID {dealer_id} was not found.")

        sap_code = str(dealer["sap_code"] or "").strip()
        existing = conn.execute(
            "SELECT id FROM dealer_targets WHERE sap_code=? AND month_year=? ORDER BY id LIMIT 1",
            (sap_code, month_year),
        ).fetchone() if sap_code else conn.execute(
            "SELECT id FROM dealer_targets WHERE dealer_name=? AND month_year=? ORDER BY id LIMIT 1",
            (dealer["dealer_name"], month_year),
        ).fetchone()
        if existing:
            conn.execute(
                "UPDATE dealer_targets SET dealer_name=?,sap_code=?,target_amount=?,achieved_amount=?,month_year=? WHERE id=?",
                (dealer["dealer_name"], sap_code, target_amount, achieved_amount, month_year, existing["id"]),
            )
        else:
            conn.execute(
                "INSERT INTO dealer_targets(dealer_name,sap_code,target_amount,achieved_amount,month_year) VALUES(?,?,?,?,?)",
                (dealer["dealer_name"], sap_code, target_amount, achieved_amount, month_year),
            )
        saved_count += 1
    return saved_count


@app.route("/save_dealer_targets", methods=["POST"])
def save_dealer_targets():
    if not admin_required():
        return redirect(url_for("admin_login"))
    month_year = (request.form.get("month_year") or datetime.now().strftime("%Y-%m")).strip()
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", month_year):
        abort(400, description="Choose a valid target month.")

    conn = db()
    try:
        _ensure_tsst_schema(conn)
        saved_count = _save_dealer_targets_bulk(conn, month_year, request.form)
        conn.commit()
        flash(f"{saved_count} dealer target records saved successfully.", "success")
        return redirect(url_for("dealer_targets", month_year=month_year))
    except ValueError as exc:
        conn.rollback()
        flash(str(exc), "danger")
        return redirect(url_for("dealer_targets", month_year=month_year))
    except sqlite3.Error:
        conn.rollback()
        app.logger.exception("Could not save bulk dealer targets")
        flash("Could not save dealer targets because of a database error.", "danger")
        return redirect(url_for("dealer_targets", month_year=month_year))
    finally:
        conn.close()


@app.route("/admin/dealer-targets", methods=["GET", "POST"])
def dealer_targets():
    if not admin_required():
        return redirect(url_for("admin_login"))

    current_month = datetime.now().strftime("%Y-%m")
    month_year = (request.values.get("month_year") or current_month).strip()
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", month_year):
        abort(400, description="Choose a valid target month.")

    conn = db()
    try:
        _ensure_tsst_schema(conn)
        if request.method == "POST":
            action = request.form.get("action", "").strip()
            try:
                target_id = request.form.get("target_id", type=int)
                if action == "delete":
                    if not target_id or target_id < 1:
                        raise ValueError("Select a valid dealer target to delete.")
                    conn.execute("DELETE FROM dealer_targets WHERE id=?", (target_id,))
                    flash("Dealer target record deleted.", "success")
                elif action == "bulk":
                    saved_count = _save_dealer_targets_bulk(conn, month_year, request.form)
                    flash(f"{saved_count} dealer target records saved successfully.", "success")
                elif action in {"add", "update"}:
                    dealer_name = request.form.get("dealer_name", "").strip()
                    sap_code = request.form.get("sap_code", "").strip()
                    if not dealer_name:
                        raise ValueError("Dealer name is required.")
                    if len(dealer_name) > 150 or len(sap_code) > 50:
                        raise ValueError("Dealer name must be 150 characters or fewer and SAP code 50 characters or fewer.")
                    target_amount = float(request.form.get("target_amount", ""))
                    achieved_amount = float(request.form.get("achieved_amount", ""))
                    if (
                        not math.isfinite(target_amount) or target_amount < 0
                        or not math.isfinite(achieved_amount) or achieved_amount < 0
                    ):
                        raise ValueError("Target and achieved amounts must be valid non-negative numbers.")
                    if action == "add":
                        conn.execute(
                            """INSERT INTO dealer_targets
                               (dealer_name,sap_code,target_amount,achieved_amount,month_year)
                               VALUES(?,?,?,?,?)""",
                            (dealer_name, sap_code, target_amount, achieved_amount, month_year)
                        )
                        flash("Dealer target record added.", "success")
                    else:
                        if not target_id or target_id < 1:
                            raise ValueError("Select a valid dealer target to update.")
                        conn.execute(
                            """UPDATE dealer_targets
                               SET dealer_name=?,sap_code=?,target_amount=?,achieved_amount=?,month_year=?
                               WHERE id=?""",
                            (dealer_name, sap_code, target_amount, achieved_amount, month_year, target_id)
                        )
                        flash("Dealer target record updated.", "success")
                else:
                    raise ValueError("Unknown dealer target action.")
                conn.commit()
                return redirect(url_for("dealer_targets", month_year=month_year))
            except ValueError as exc:
                conn.rollback()
                flash(str(exc), "danger")
            except sqlite3.Error:
                conn.rollback()
                app.logger.exception("Could not save dealer target")
                flash("Could not save the dealer target because of a database error.", "danger")

        targets = conn.execute(
            """SELECT id,dealer_name,sap_code,target_amount,achieved_amount,month_year
               FROM dealer_targets WHERE month_year=? ORDER BY dealer_name,id""",
            (month_year,)
        ).fetchall()
        dealer_rows = conn.execute(
            """SELECT d.id,d.dealer_name,d.sap_code,d.town
               FROM dealers d WHERE d.active=1
               ORDER BY d.dealer_name,d.sap_code"""
        ).fetchall()
        target_by_sap = {
            str(row["sap_code"] or "").strip().upper(): row
            for row in targets if str(row["sap_code"] or "").strip()
        }
        dealers = []
        for dealer in dealer_rows:
            existing = target_by_sap.get(str(dealer["sap_code"] or "").strip().upper())
            dealers.append({
                "id": dealer["id"],
                "name": dealer["dealer_name"],
                "dealer_name": dealer["dealer_name"],
                "sap_code": dealer["sap_code"] or "",
                "town": dealer["town"] or "",
                "target": existing["target_amount"] if existing else 0,
                "achievement": existing["achieved_amount"] if existing else 0,
            })
        return render_template("admin/dealer_targets.html", targets=targets, dealers=dealers, month_year=month_year)
    finally:
        conn.close()


@app.route("/admin/tsst-management", methods=["GET", "POST"])
def tsst_management():
    if not admin_required():
        return redirect(url_for("admin_login"))

    now = datetime.now()
    try:
        year = int(request.values.get("year", now.year))
        month = int(request.values.get("month", now.month))
    except (TypeError, ValueError):
        abort(400, description="A valid reporting year and month are required.")
    if not 2020 <= year <= 2100 or not 1 <= month <= 12:
        abort(400, description="Choose a valid reporting month and year.")

    conn = db()
    try:
        _ensure_tsst_schema(conn)
        if request.method == "POST":
            action = request.form.get("action", "").strip()
            try:
                if action == "metric_delete":
                    record_id = request.form.get("record_id", type=int)
                    if not record_id or record_id < 1:
                        raise ValueError("Select a valid TSST metric record to delete.")
                    conn.execute("DELETE FROM tsst_management_records WHERE id=?", (record_id,))
                    flash("TSST metric record deleted.", "success")
                elif action == "metric_save":
                    record_id = request.form.get("record_id", type=int)
                    employee_name = request.form.get("employee_name", "").strip()
                    emp_code = request.form.get("emp_code", "").strip()
                    metric_name = request.form.get("metric_name", "").strip()
                    score = float(request.form.get("score", ""))
                    metric_date = request.form.get("metric_date", "").strip()
                    if not employee_name or not metric_name:
                        raise ValueError("Employee name and metric name are required.")
                    if len(employee_name) > 150 or len(emp_code) > 50 or len(metric_name) > 100:
                        raise ValueError("Employee name, code, or metric name exceeds its maximum length.")
                    if not math.isfinite(score) or score < 0:
                        raise ValueError("Score must be a valid non-negative number.")
                    try:
                        date.fromisoformat(metric_date)
                    except ValueError:
                        raise ValueError("Enter a valid metric date.") from None
                    if record_id:
                        conn.execute(
                            """UPDATE tsst_management_records
                               SET employee_name=?,emp_code=?,metric_name=?,score=?,metric_date=?
                               WHERE id=?""",
                            (employee_name, emp_code, metric_name, score, metric_date, record_id)
                        )
                        flash("TSST metric record updated.", "success")
                    else:
                        conn.execute(
                            """INSERT INTO tsst_management_records
                               (employee_name,emp_code,metric_name,score,metric_date)
                               VALUES(?,?,?,?,?)""",
                            (employee_name, emp_code, metric_name, score, metric_date)
                        )
                        flash("TSST metric record added.", "success")
                    year, month = date.fromisoformat(metric_date).year, date.fromisoformat(metric_date).month
                else:
                    user_id = int(request.form.get("user_id", ""))
                    user = conn.execute(
                        "SELECT id FROM users WHERE id=? AND role IN ('USER','MANAGER')",
                        (user_id,)
                    ).fetchone()
                    if not user:
                        raise ValueError("Select a valid user or manager account.")

                    if action == "designation":
                        designation = request.form.get("designation", "").strip().upper()
                        if designation not in {"", *VALID_ROLES}:
                            raise ValueError("Choose a valid TSST role.")
                        conn.execute(
                            "UPDATE users SET tsst_designation=? WHERE id=?",
                            (designation, user_id)
                        )
                        flash("TSST designation updated.", "success")
                    elif action == "target":
                        raw_target = request.form.get("target_amount", "").strip()
                        target_amount = float(raw_target)
                        if not math.isfinite(target_amount) or target_amount < 0:
                            raise ValueError("Monthly target must be a valid non-negative amount.")
                        conn.execute(
                            """INSERT INTO monthly_targets(user_id,year,month,target_amount)
                               VALUES(?,?,?,?)
                               ON CONFLICT(user_id,year,month)
                               DO UPDATE SET target_amount=EXCLUDED.target_amount""",
                            (user_id, year, month, target_amount)
                        )
                        flash("Monthly sales target saved.", "success")
                    else:
                        raise ValueError("Unknown TSST management action.")

                conn.commit()
                return redirect(url_for("tsst_management", year=year, month=month))
            except ValueError as exc:
                conn.rollback()
                flash(str(exc), "danger")
            except sqlite3.Error:
                conn.rollback()
                app.logger.exception("Could not update TSST management data")
                flash("Could not save TSST management data because of a database error.", "danger")

        start_date, end_date = _month_bounds(year, month)
        users = conn.execute(
            """SELECT u.id,u.name,u.user_code,u.email,u.role,u.is_active,u.tsst_designation,
                      COALESCE(mt.target_amount,0) AS target_amount,
                      COALESCE(s.achievement,0) AS achievement
               FROM users u
               LEFT JOIN monthly_targets mt
                 ON mt.user_id=u.id AND mt.year=? AND mt.month=?
               LEFT JOIN (
                   SELECT user_id,SUM(total_amount) AS achievement
                   FROM orders
                   WHERE status IN ('CONFIRMED','COMPLETED')
                     AND CAST(order_date AS TIMESTAMP)::date BETWEEN ?::date AND ?::date
                   GROUP BY user_id
               ) s ON s.user_id=u.id
               WHERE u.role IN ('USER','MANAGER')
               ORDER BY u.tsst_designation,u.name""",
            (year, month, start_date, end_date)
        ).fetchall()
        metrics = conn.execute(
            """SELECT id,employee_name,emp_code,metric_name,score,metric_date
               FROM tsst_management_records
               WHERE metric_date BETWEEN ? AND ?
               ORDER BY metric_date DESC,id DESC""",
            (start_date, end_date)
        ).fetchall()
        report_rows = []
        for user in users:
            row = dict(user)
            row["remaining"] = max(0.0, float(row["target_amount"] or 0) - float(row["achievement"] or 0))
            row["achievement_percent"] = (
                float(row["achievement"] or 0) / float(row["target_amount"]) * 100
                if float(row["target_amount"] or 0) > 0 else 0.0
            )
            report_rows.append(row)
        totals = {
            "target": sum(float(row["target_amount"] or 0) for row in report_rows),
            "achievement": sum(float(row["achievement"] or 0) for row in report_rows),
        }
        totals["remaining"] = max(0.0, totals["target"] - totals["achievement"])
        return render_template(
            "admin/tsst_management.html", users=report_rows, year=year, month=month,
            month_label=datetime(year, month, 1).strftime("%B %Y"), totals=totals,
            metrics=metrics, valid_roles=VALID_ROLES
        )
    finally:
        conn.close()


