        "ACH. (16th to 22nd) PRI.", "ACH. (16th to 22nd) SEC.",
        "ACH. (23rd to 31st) PRI.", "ACH. (23rd to 31st) SEC.",
        "TOTAL ACHIEVEMENT PRI.", "TOTAL ACHIEVEMENT SEC.",
        "Ach. % PRI.", "Ach. % SEC.", "DIFFERENCE PRI.", "DIFFERENCE SEC.",
