@app.route("/products")
def products():
    # A fresh Products navigation starts a new order flow. Brand tabs within
    # the same flow do not pass reset=1, so multi-brand selections are kept.
    fresh_reset = request.args.get("reset") == "1"
    if fresh_reset:
        session.pop("product_selection", None)
        session.pop("primary_draft", None)
    q = request.args.get("q", "").strip()
    category = request.args.get("category", "").strip()
    brand = request.args.get("brand", "").strip()
    dealer_id = request.args.get("dealer_id", "").strip()
    conn = db()
    seed_nv_scheme_rules(conn)
    sql = "SELECT * FROM products WHERE status='ACTIVE' AND stock>0"
    params = []
    if q:
        sql += " AND (name LIKE ? OR product_code LIKE ? OR category LIKE ? OR brand LIKE ?)"
        params += [f"%{q}%", f"%{q}%", f"%{q}%", f"%{q}%"]
    if brand:
        sql += " AND brand=?"; params.append(brand)
    if category:
        sql += " AND category=?"; params.append(category)
    sql += " ORDER BY name"
    raw_rows = conn.execute(sql, params).fetchall()
    rows=[]
    for r in raw_rows:
        item=dict(r)
        if item.get('brand') in ('ENVY','Pure Home'):
            rule=get_nv_scheme(conn,item['id'])
            if rule:
                item['trade_promotion']=float(rule['trade_promotion'] or 0)
                item['slab1_percent']=float(rule['slab1_percent'] or 0); item['slab1_cs']=float(rule['slab1_cs'] or 0)
                item['slab2_percent']=float(rule['slab2_percent'] or 0); item['slab2_cs']=float(rule['slab2_cs'] or 0)
                item['slab3_percent']=float(rule['slab3_percent'] or 0); item['slab3_cs']=float(rule['slab3_cs'] or 0)
        flavor_names=[]
        if item.get('flavor'):
            flavor_names=[x.strip() for x in str(item['flavor']).replace(';', ',').split(',') if x.strip()]
        if item.get('category'):
            category_flavors=conn.execute("""SELECT f.name FROM flavors f JOIN categories c ON c.id=f.category_id WHERE c.name=? ORDER BY f.name""", (item['category'],)).fetchall()
            for fr in category_flavors:
                if fr['name'] not in flavor_names: flavor_names.append(fr['name'])
        item['flavors_list']=flavor_names
        item['qty_min'], item['qty_step']=quantity_rule_for_product(item.get('category'),item.get('brand'),item.get('name'))
        rows.append(item)
    cats = conn.execute("SELECT DISTINCT category FROM products WHERE category IS NOT NULL AND category<>'' ORDER BY category").fetchall()
    brands = conn.execute("SELECT brand FROM products WHERE brand IS NOT NULL AND TRIM(brand)<>'' GROUP BY brand ORDER BY CASE brand WHEN 'ENVY' THEN 0 WHEN 'Pure Home' THEN 1 ELSE 2 END, brand").fetchall()
    brand_categories={}
    for b in brands:
        brand_categories[b['brand']]=conn.execute("SELECT DISTINCT category FROM products WHERE brand=? AND category IS NOT NULL AND category<>'' ORDER BY category",(b['brand'],)).fetchall()

    # Dealer selector for the integrated Primary Order flow.
    if login_required():
        if session.get('role') == 'ADMIN':
            dealers=conn.execute("SELECT * FROM dealers WHERE active=1 ORDER BY dealer_name").fetchall()
        else:
            u=conn.execute("SELECT user_code,name FROM users WHERE id=?",(session.get('user_id'),)).fetchone()
            dealers=conn.execute("SELECT * FROM dealers WHERE active=1 AND emp_code=? ORDER BY dealer_name",(u['user_code'],)).fetchall() if u and u['user_code'] else (conn.execute("SELECT * FROM dealers WHERE active=1 AND emp_name=? ORDER BY dealer_name",(u['name'],)).fetchall() if u else [])
    else:
        dealers=[]

    draft=session.get('primary_draft') or {}
    draft_items=draft.get('items',[]) if isinstance(draft,dict) else []
    selected_map={str(x.get('product_id')):x for x in draft_items}
    # Persist the in-progress multi-brand product selection server-side as well
    # as in the browser. This prevents selections from disappearing when the
    # user switches ENVY -> Pure Home -> another brand before opening Order Page.
    saved_selection=session.get('product_selection') or {}
    if isinstance(saved_selection,dict):
        for pid, qty in (saved_selection.get('items') or {}).items():
            selected_map.setdefault(str(pid), {'product_id':int(pid), 'quantity':int(qty)})
    selected_dealer_id=str(saved_selection.get('dealer_id','')) if isinstance(saved_selection,dict) else ''
    if not selected_dealer_id and isinstance(draft,dict):
        selected_dealer_id=str(draft.get('dealer_id',''))
    if dealer_id: selected_dealer_id=dealer_id

    # Group ENVY and Pure Home separately by MRP. If the catalogue contains
    # an exact duplicate display row (same brand/name/MRP/rate), show it once.
    brand_groups={}
    if brand in ('ENVY', 'Pure Home'):
        seen=set()
        grouped={}
        for p in rows:
            key=(p.get('brand'), p.get('name'), float(p.get('mrp') or p.get('price') or 0),
                 float(p.get('price') or 0))
            if key in seen:
                continue
            seen.add(key)
            mrp_key=float(p.get('mrp') or p.get('price') or 0)
            grouped.setdefault(mrp_key,[]).append(p)
        brand_groups=dict(sorted(grouped.items(), key=lambda x:x[0]))

    conn.close()
    saved_items = (saved_selection.get('items') or {}) if isinstance(saved_selection,dict) else {}
    return render_template("products.html", products=rows, categories=cats, brands=brands,
                           brand_categories=brand_categories, q=q, category=category, brand=brand,
                           dealers=dealers, selected_dealer_id=selected_dealer_id,
                           selected_map=selected_map, selection_state={'dealer_id': selected_dealer_id, 'items': saved_items},
                           fresh_reset=fresh_reset, envy_groups=brand_groups, brand_groups=brand_groups)

@app.route("/product/<int:product_id>")
def product_details(product_id):
    conn = db()
    product = conn.execute("SELECT * FROM products WHERE id=?", (product_id,)).fetchone()
    flavor_options = []
    if product and product["category"]:
        flavor_options = conn.execute("""
            SELECT f.name
            FROM flavors f
            JOIN categories c ON c.id=f.category_id
            WHERE c.name=? ORDER BY f.name
        """, (product["category"],)).fetchall()
    if not product:
        conn.close()
        flash("Product not found.", "danger")
        return redirect(url_for("products"))
    qty_min, qty_step = quantity_rule_for_product(product["category"], product["brand"], product["name"])
    scheme = get_nv_scheme(conn, product_id) if product["brand"] in ("ENVY", "Pure Home") else None
    conn.close()
    return render_template("product_details.html", product=product, flavor_options=flavor_options, qty_min=qty_min, qty_step=qty_step, scheme=scheme)

@app.route("/cart")
def cart():
    cart_data = session.get("cart", {})
    items, total = [], 0
    conn = db()
    for key, qty in cart_data.items():
        key = str(key)
        if "|" in key:
            pid_text, flavor = key.split("|", 1)
        else:
            pid_text, flavor = key, ""
        try:
            pid, qty = int(pid_text), int(qty)
        except ValueError:
            continue
        p = conn.execute("SELECT * FROM products WHERE id=?", (pid,)).fetchone()
        if not p:
            continue
        subtotal = p["price"] * qty
        items.append({"product":p, "quantity":qty, "flavor":flavor, "cart_key":key, "subtotal":subtotal})
        total += subtotal
    conn.close()
    return render_template("cart.html", items=items, total=total)

@app.route("/cart/add/<int:product_id>", methods=["POST"])
def add_cart(product_id):
    try:
        qty = int(request.form.get("quantity", 0))
    except (TypeError, ValueError):
        qty = 0

    if qty < 12:
        flash("Minimum order quantity is 12.", "warning")
        return redirect(url_for("product_details", product_id=product_id))

    flavor = request.form.get("flavor", "").strip()
    conn = db()
    p = conn.execute("SELECT * FROM products WHERE id=? AND status='ACTIVE'", (product_id,)).fetchone()
    flavor_rows = []
    if p and p["category"]:
        flavor_rows = conn.execute("""
            SELECT f.name
            FROM flavors f JOIN categories c ON c.id=f.category_id
            WHERE c.name=? ORDER BY f.name
        """, (p["category"],)).fetchall()
    conn.close()

    if not p:
        flash("Product not found.", "danger")
        return redirect(url_for("products"))

    allowed = {r["name"] for r in flavor_rows}
    if flavor_rows and not flavor:
        flash("Please select a flavor.", "warning")
        return redirect(url_for("product_details", product_id=product_id))
    if flavor_rows and flavor not in allowed:
        flash("Invalid flavor selected.", "danger")
        return redirect(url_for("product_details", product_id=product_id))
    if qty > p["stock"]:
        flash("Requested quantity exceeds available stock.", "danger")
        return redirect(url_for("product_details", product_id=product_id))

    key = f"{product_id}|{flavor}"
    cart_data = session.get("cart", {})
    new_qty = int(cart_data.get(key, 0)) + qty
    if new_qty > p["stock"]:
        flash("Cart quantity exceeds available stock.", "danger")
        return redirect(url_for("product_details", product_id=product_id))
    cart_data[key] = new_qty
    session["cart"] = cart_data
    flash(f"{p['name']} ({flavor or 'Standard'}) added to cart.", "success")
    return redirect(url_for("cart"))

@app.route("/cart/remove/<path:cart_key>", methods=["POST"])
def remove_cart(cart_key):
    cart_data = session.get("cart", {})
    cart_data.pop(cart_key, None)
    session["cart"] = cart_data
    return redirect(url_for("cart"))

@app.route("/checkout", methods=["POST"])
def checkout():
    if not login_required():
        flash("Please log in before placing an order.", "warning")
        return redirect(url_for("login"))
    cart_data = session.get("cart", {})
    if not cart_data:
        flash("Your cart is empty.", "warning")
        return redirect(url_for("cart"))

    conn = db()
    try:
        total = 0
        selected = []

        # Lock products in a stable order. This prevents two simultaneous
        # customers from both consuming the same closing stock.
        cart_entries = []
        for cart_key, raw_qty in cart_data.items():
            if "|" in str(cart_key):
                pid_text, flavor = str(cart_key).split("|", 1)
            else:
                pid_text, flavor = str(cart_key), ""
            cart_entries.append((int(pid_text), int(raw_qty), flavor))
        cart_entries.sort(key=lambda x: x[0])

        locked_products = {}
        for pid, qty, flavor in cart_entries:
            if qty < 12:
                raise ValueError("Minimum order quantity is 12.")
            if qty <= 0:
                raise ValueError("Quantity must be greater than zero.")

            if pid not in locked_products:
                p = conn.execute("SELECT * FROM products WHERE id=? AND status='ACTIVE' FOR UPDATE", (pid,)).fetchone()
                if not p:
                    raise ValueError("Product is no longer available.")

                depot = conn.execute(
                    "SELECT * FROM depot_stock WHERE product_id=? FOR UPDATE", (pid,)
                ).fetchone()
                # Depot stock is the authoritative live stock when available;
                # products.stock remains synchronised for catalogue display.
                available = int(depot["quantity"] if depot else p["stock"] or 0)
                locked_products[pid] = (p, depot, available)
            else:
                p, depot, available = locked_products[pid]

            if qty > available:
                raise ValueError(
                    f"Insufficient stock for {p['name']}. Available stock: {available}. Requested: {qty}."
                )

            # Reserve the quantity in-memory first; the actual database updates
            # happen only after every cart line has passed validation.
            p, depot, available = locked_products[pid]
            locked_products[pid] = (p, depot, available - qty)
            line = float(p["price"] or 0) * qty
            total += line
            selected.append((p, qty, line, flavor))

        order_number = "SMR-" + datetime.now().strftime("%Y%m%d%H%M%S%f")[-12:]
        now = datetime.now().isoformat(timespec="seconds")
        cur = conn.execute(
            "INSERT INTO orders(user_id,order_number,total_amount,status,order_date,billing_date) VALUES(?,?,?,?,?,?)",
            (session["user_id"], order_number, total, "COMPLETED", now, now[:10])
        )
        order_id = cur.lastrowid

        # Apply the exact reserved quantities after all validation succeeded.
        for p, qty, line, flavor in selected:
            conn.execute(
                "INSERT INTO order_items(order_id,product_id,quantity,unit_price,total_price,flavor,mrp,scheme,discount_amount) VALUES(?,?,?,?,?,?,?,?,?)",
                (order_id, p["id"], qty, p["price"], line, flavor, p["mrp"], p["scheme"], p["discount_amount"])
            )
            conn.execute(
                "UPDATE products SET stock=stock-?,updated_at=? WHERE id=?",
                (qty, now, p["id"])
            )
            conn.execute(
                "UPDATE depot_stock SET quantity=GREATEST(0,quantity-?),updated_at=? WHERE product_id=?",
                (qty, now, p["id"])
            )
            conn.execute(
                "UPDATE inventory SET available_quantity=GREATEST(0,available_quantity-?),updated_at=? WHERE product_id=?",
                (qty, now, p["id"])
            )

        conn.commit()
        session["cart"] = {}
        flash(f"Order {order_number} placed successfully.", "success")
        return redirect(url_for("my_orders"))
    except Exception as e:
        conn.rollback()
        flash(str(e), "danger")
        return redirect(url_for("cart"))
    finally:
        conn.close()

@app.route("/my-orders/<int:order_id>/edit", methods=["GET","POST"])
def my_order_edit(order_id):
    if not login_required(): return redirect(url_for("login"))
    conn=db()
    order=conn.execute("SELECT o.*,d.dealer_name,d.town,d.sap_code FROM orders o LEFT JOIN dealers d ON d.id=o.dealer_id WHERE o.id=? AND o.user_id=?",(order_id,session["user_id"])).fetchone()
    if not order:
        conn.close(); flash("Order not found.","danger"); return redirect(url_for("my_orders"))
    if normalize_order_status(order["status"]) != "PENDING":
        conn.close(); flash("Only Pending orders can be edited.","warning"); return redirect(url_for("order_details",order_id=order_id))
    if request.method=="POST":
        try:
            keep_ids=[int(x) for x in request.form.getlist("item_id") if str(x).isdigit()]
            delete_ids={int(x) for x in request.form.getlist("delete_item_id") if str(x).isdigit()}
            items=[]
            for item_id in keep_ids:
                if item_id in delete_ids: continue
                row=conn.execute("SELECT oi.*,p.name product_name,p.product_code,p.brand,p.category,p.mrp,p.price,p.case_size FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.id=? AND oi.order_id=? AND p.status='ACTIVE'",(item_id,order_id)).fetchone()
                if not row: continue
                qty=int(request.form.get(f"quantity_{item_id}",row["quantity"]))
                qmin,qstep=quantity_rule_for_product(row["category"],row["brand"],row["product_name"])
                if qty<qmin or (qty-qmin)%qstep!=0: raise ValueError(f"Quantity for {row['product_name']} must be {qmin}, {qmin+qstep}, {qmin+2*qstep}... only.")
                items.append({"product_id":row["product_id"],"product_name":row["product_name"],"product_code":row["product_code"],"brand":row["brand"],"category":row["category"],"flavor":row["flavor"] or "","mrp":float(row["mrp"] or row["price"] or 0),"rate":float(row["price"] or 0),"quantity":qty,"case_size":row["case_size"] or 0,"item_id":item_id})
            add_pid=request.form.get("add_product_id","").strip()
            if add_pid:
                pid=int(add_pid); p=conn.execute("SELECT * FROM products WHERE id=? AND status='ACTIVE'",(pid,)).fetchone()
                if not p: raise ValueError("Selected product is not active.")
                qty=int(request.form.get("add_quantity","0") or 0); qmin,qstep=quantity_rule_for_product(p["category"],p["brand"],p["name"])
                if qty<qmin or (qty-qmin)%qstep!=0: raise ValueError(f"Quantity for {p['name']} must be {qmin}, {qmin+qstep}, {qmin+2*qstep}... only.")
                items.append({"product_id":p["id"],"product_name":p["name"],"product_code":p["product_code"],"brand":p["brand"],"category":p["category"],"flavor":"","mrp":float(p["mrp"] or p["price"] or 0),"rate":float(p["price"] or 0),"quantity":qty,"case_size":p["case_size"] or 0,"item_id":None})
            if not items: raise ValueError("An order must contain at least one product.")
            items,_groups=apply_overall_schemes(conn,items)
            conn.execute("DELETE FROM order_items WHERE order_id=?",(order_id,))
            for i in items:
                conn.execute("INSERT INTO order_items(order_id,product_id,quantity,unit_price,total_price,flavor,mrp,scheme,discount_amount) VALUES(?,?,?,?,?,?,?,?,?)",(order_id,i["product_id"],i["quantity"],i["rate"],i["total_price"],i.get("flavor",""),i["mrp"],i["scheme"],i["discount_amount"]))
            total=round(sum(i["total_price"] for i in items),2)
            conn.execute("UPDATE orders SET total_amount=? WHERE id=? AND status='PENDING'",(total,order_id))
            po=conn.execute("SELECT id FROM primary_orders WHERE reference_no=?",(order["order_number"],)).fetchone()
            if po:
                conn.execute("DELETE FROM primary_order_items WHERE primary_order_id=?",(po["id"],))
                for i in items:
                    conn.execute("INSERT INTO primary_order_items(primary_order_id,product_id,mrp,scheme,net_price,quantity,total_price,flavor) VALUES(?,?,?,?,?,?,?,?)",(po["id"],i["product_id"],i["mrp"],i["scheme"],i["net_price"],i["quantity"],i["total_price"],i.get("flavor","")))
                conn.execute("UPDATE primary_orders SET product_id=?,quantity=?,status='PENDING' WHERE id=?",(items[0]["product_id"],sum(i["quantity"] for i in items),po["id"]))
            conn.commit(); flash("Pending order updated successfully with the latest overall scheme.","success"); return redirect(url_for("order_details",order_id=order_id))
        except (ValueError,sqlite3.Error) as e:
            conn.rollback(); flash(str(e),"danger")
    raw=conn.execute("SELECT oi.*,p.name product_name,p.product_code,p.brand,p.category,p.mrp,p.price,p.case_size FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id",(order_id,)).fetchall()
    products=conn.execute("SELECT * FROM products WHERE status='ACTIVE' ORDER BY brand,name").fetchall()
    items=[]
    for row in raw:
        d=dict(row); d["qty_min"],d["qty_step"]=quantity_rule_for_product(d.get("category"),d.get("brand"),d.get("product_name")); items.append(d)
    conn.close(); return render_template("order_edit.html",order=order,items=items,products=products)

@app.route("/my-orders")
def my_orders():
    if not login_required(): return redirect(url_for("login"))
    status=normalize_order_status(request.args.get("status")) if request.args.get("status") else ""
    selected_date=(request.args.get("date") or datetime.now().strftime("%Y-%m-%d")).strip()
    conn=db()
    sql="SELECT o.*,d.dealer_name,d.town,CASE WHEN o.status IN ('COMPLETED','PROCESSING','APPROVED','CONFIRMED') THEN 'CONFIRMED' WHEN o.status IN ('CANCELLED','REJECTED','CANCELED') THEN 'CANCELED' ELSE 'PENDING' END AS display_status, CASE WHEN NULLIF(CAST(o.billing_date AS TEXT),'') IS NOT NULL THEN CAST(o.billing_date AS DATE) ELSE CAST(o.order_date AS TIMESTAMP)::date END AS display_date FROM orders o LEFT JOIN dealers d ON d.id=o.dealer_id WHERE o.user_id=? AND (CASE WHEN NULLIF(CAST(o.billing_date AS TEXT),'') IS NOT NULL THEN CAST(o.billing_date AS DATE) ELSE CAST(o.order_date AS TIMESTAMP)::date END)=?::date"
    params=[session["user_id"], selected_date]
    if status:
        sql += " AND o.status=?"; params.append(status)
    sql += " ORDER BY o.id DESC"
    orders=conn.execute(sql,params).fetchall(); conn.close()
    return render_template("orders.html",orders=orders,status=status,selected_date=selected_date,admin=False)

