# ---------------- ADMIN CATEGORIES & FLAVORS ----------------

@app.route("/admin/categories", methods=["GET", "POST"])
def admin_categories():
    if not admin_required():
        return redirect(url_for("admin_login"))
    conn = db()

    if request.method == "POST":
        name = request.form.get("name", "").strip()
        description = request.form.get("description", "").strip()
        if not name:
            flash("Category name is required.", "danger")
        else:
            now = datetime.now().isoformat(timespec="seconds")
            try:
                conn.execute(
                    "INSERT INTO categories(name,description,created_at,updated_at) VALUES(?,?,?,?)",
                    (name, description, now, now)
                )
                conn.commit()
                flash("Category added successfully.", "success")
            except sqlite3.IntegrityError:
                flash("That category already exists.", "warning")

    categories = conn.execute("""
        SELECT c.*,
               (SELECT COUNT(*) FROM products p WHERE p.category=c.name) AS product_count
        FROM categories c ORDER BY c.name
    """).fetchall()

    category_data = []
    for c in categories:
        flavors = conn.execute(
            "SELECT * FROM flavors WHERE category_id=? ORDER BY name",
            (c["id"],)
        ).fetchall()
        category_data.append({
            "id": c["id"], "name": c["name"], "description": c["description"],
            "product_count": c["product_count"], "flavors": flavors
        })

    conn.close()
    return render_template("admin/categories.html", categories=category_data)


@app.route("/admin/categories/<int:category_id>/edit", methods=["GET", "POST"])
def admin_category_edit(category_id):
    if not admin_required():
        return redirect(url_for("admin_login"))
    conn = db()
    category = conn.execute("SELECT * FROM categories WHERE id=?", (category_id,)).fetchone()
    if not category:
        conn.close()
        flash("Category not found.", "danger")
        return redirect(url_for("admin_categories"))

    if request.method == "POST":
        new_name = request.form.get("name", "").strip()
        description = request.form.get("description", "").strip()
        if not new_name:
            flash("Category name is required.", "danger")
        else:
            now = datetime.now().isoformat(timespec="seconds")
            try:
                conn.execute(
                    "UPDATE products SET category=?, updated_at=? WHERE category=?",
                    (new_name, now, category["name"])
                )
                conn.execute(
                    "UPDATE categories SET name=?, description=?, updated_at=? WHERE id=?",
                    (new_name, description, now, category_id)
                )
                conn.commit()
                conn.close()
                flash("Category updated successfully.", "success")
                return redirect(url_for("admin_categories"))
            except sqlite3.IntegrityError:
                flash("That category name already exists.", "warning")
    conn.close()
    return render_template("admin/category_form.html", category=category)


@app.route("/admin/categories/<int:category_id>/delete", methods=["POST"])
def admin_category_delete(category_id):
    if not admin_required():
        return redirect(url_for("admin_login"))
    conn = db()
    category = conn.execute("SELECT * FROM categories WHERE id=?", (category_id,)).fetchone()
    if not category:
        conn.close()
        flash("Category not found.", "danger")
        return redirect(url_for("admin_categories"))

    used = conn.execute(
        "SELECT COUNT(*) AS c FROM products WHERE category=?", (category["name"],)
    ).fetchone()["c"]
    if used:
        conn.close()
        flash("This category is used by products. Move those products first.", "warning")
        return redirect(url_for("admin_categories"))

    conn.execute("DELETE FROM flavors WHERE category_id=?", (category_id,))
    conn.execute("DELETE FROM categories WHERE id=?", (category_id,))
    conn.commit()
    conn.close()
    flash("Category deleted successfully.", "success")
    return redirect(url_for("admin_categories"))


