# ---------------- SHARED OPERATIONS ----------------

def _smr_mapped_dealers(conn):
    if session.get("role") == "ADMIN":
        return conn.execute("SELECT * FROM dealers WHERE active=1 ORDER BY dealer_name").fetchall()
    user = conn.execute("SELECT name,user_code FROM users WHERE id=?", (session.get("user_id"),)).fetchone()
    if not user:
        return []
    return conn.execute("SELECT * FROM dealers WHERE active=1 AND (emp_code=? OR emp_name=?) ORDER BY dealer_name",
                        (user.get("user_code") or "", user.get("name") or "")).fetchall()

def _smr_build_rows(conn, dealer_id):
    products = conn.execute("""
        SELECT p.id,p.product_code,p.name,p.category,p.mrp,p.price,
               COALESCE(ds.quantity,0) AS opening_stock,
               COALESCE(inv.available_quantity,0) AS live_stock
        FROM products p
        LEFT JOIN depot_stock ds ON ds.product_id=p.id
        LEFT JOIN inventory inv ON inv.product_id=p.id
        WHERE p.status='ACTIVE'
        ORDER BY COALESCE(NULLIF(p.category,''),'Uncategorized'), p.name, p.mrp, p.id
    """).fetchall()
    primary = {}
    secondary = {}
    if dealer_id:
        for r in conn.execute("""
            SELECT oi.product_id, COALESCE(SUM(oi.quantity),0) qty
            FROM order_items oi JOIN orders o ON o.id=oi.order_id
            WHERE o.dealer_id=? AND COALESCE(o.order_type,'SALES ORDER')='PRIMARY ORDER'
            GROUP BY oi.product_id
        """, (dealer_id,)).fetchall():
            primary[int(r['product_id'])] = int(r['qty'] or 0)
        for r in conn.execute("""
            SELECT oi.product_id, COALESCE(SUM(oi.quantity),0) qty
            FROM order_items oi JOIN orders o ON o.id=oi.order_id
            WHERE o.dealer_id=? AND COALESCE(o.order_type,'SALES ORDER')='SECONDARY ORDER'
            GROUP BY oi.product_id
        """, (dealer_id,)).fetchall():
            secondary[int(r['product_id'])] = int(r['qty'] or 0)
    rows=[]
    for p in products:
        pid=int(p['id'])
        rows.append({'id':pid,'product_code':p['product_code'],'name':p['name'],
                     'category':p['category'] or 'Uncategorized','mrp':float(p['mrp'] or 0),
                     'opening':int(p['opening_stock'] or 0),'primary':int(primary.get(pid,0)),
                     'secondary':int(secondary.get(pid,0)),'closing':int(p['live_stock'] or 0)})
    return rows


def _smr_group_rows(rows):
    by_category={}
    for row in rows:
        by_category.setdefault(row['category'], []).append(row)
    return [{'category':c,'rows':by_category[c]} for c in sorted(by_category,key=lambda x:x.lower())]


@app.route("/smr")
def smr():
    if not login_required(): return redirect(url_for("login"))
    conn=db()
    try:
        dealers=_smr_mapped_dealers(conn)
        requested=request.args.get('dealer_id', type=int)
        selected=None
        if requested and requested in {int(d['id']) for d in dealers}:
            selected=conn.execute("SELECT * FROM dealers WHERE id=? AND active=1",(requested,)).fetchone()
        if selected is None and dealers:
            selected=dealers[0]
        employee=None
        if selected:
            employee=conn.execute("SELECT * FROM users WHERE name=? OR user_code=? ORDER BY id LIMIT 1",
                                   (selected['emp_name'],selected['emp_code'])).fetchone()
        rows=_smr_build_rows(conn, selected['id'] if selected else None)
        groups=_smr_group_rows(rows)
        mapped_members=[]
        if selected:
            mapped_members=[{'name':selected['emp_name'],'code':selected['emp_code'],
                             'role':(employee['role'] if employee else 'Mapped Employee')}]
        totals={'products':len(rows),'opening':sum(r['opening'] for r in rows),
                'primary':sum(r['primary'] for r in rows),'secondary':sum(r['secondary'] for r in rows),
                'closing':sum(r['closing'] for r in rows)}
        return render_template('smr.html',dealers=dealers,selected_dealer=selected,employee=employee,
                               groups=groups,rows=rows,totals=totals,is_admin=session.get('role')=='ADMIN',
                               mapped_members=mapped_members)
    finally:
        conn.close()


@app.route('/admin/smr/mrp/<int:product_id>', methods=['POST'])
def admin_smr_mrp_edit(product_id):
    if not admin_required():
        flash('Only Admin can edit MRP.','danger'); return redirect(url_for('smr'))
    try:
        mrp=float(request.form.get('mrp','0') or 0)
        if mrp < 0: raise ValueError
    except (TypeError,ValueError):
        flash('Enter a valid MRP value.','danger'); return redirect(url_for('smr'))
    conn=db()
    try:
        product=conn.execute('SELECT id,name FROM products WHERE id=?',(product_id,)).fetchone()
        if not product: flash('Product not found.','warning')
        else:
            conn.execute('UPDATE products SET mrp=?, updated_at=? WHERE id=?',
                         (mrp,datetime.now().isoformat(timespec='seconds'),product_id))
            conn.commit(); flash(f"MRP updated for {product['name']}.",'success')
    finally:
        conn.close()
    dealer_id=request.form.get('dealer_id', type=int)
    return redirect(url_for('smr',dealer_id=dealer_id) if dealer_id else url_for('smr'))


@app.route('/smr/secondary-order', methods=['POST'])
def smr_secondary_order():
    if not login_required(): return redirect(url_for('login'))
    conn=db()
    try:
        dealers=_smr_mapped_dealers(conn); allowed={int(d['id']) for d in dealers}
        dealer_id=request.form.get('dealer_id', type=int)
        if not dealer_id or dealer_id not in allowed: raise ValueError('Please select a valid mapped dealer.')
        selected=conn.execute('SELECT * FROM dealers WHERE id=? AND active=1',(dealer_id,)).fetchone()
        selected_items=[]
        for key,value in request.form.items():
            if not key.startswith('secondary_qty_'): continue
            try: pid=int(key.rsplit('_',1)[1]); qty=int(value or 0)
            except (ValueError,TypeError): continue
            if qty <= 0: continue
            product=conn.execute("SELECT * FROM products WHERE id=? AND status='ACTIVE'",(pid,)).fetchone()
            if product: selected_items.append((product,qty))
        if not selected_items: raise ValueError('Enter at least one Secondary Order quantity.')
        now=datetime.now().isoformat(timespec='seconds'); ref='SO-'+datetime.now().strftime('%Y%m%d%H%M%S%f')[-12:]
        total=sum(float(p['price'] or p['mrp'] or 0)*qty for p,qty in selected_items)
        cur=conn.execute("""INSERT INTO orders(user_id,order_number,total_amount,status,order_date,billing_date,dealer_id,order_type)
                           VALUES(?,?,?,?,?,?,?,?)""",
                         (session['user_id'],ref,total,'COMPLETED',now,now[:10],dealer_id,'SECONDARY ORDER'))
        order_id=cur.lastrowid
        for p,qty in selected_items:
            rate=float(p['price'] or p['mrp'] or 0); mrp=float(p['mrp'] or rate)
            conn.execute("""INSERT INTO order_items(order_id,product_id,quantity,unit_price,total_price,flavor,mrp,scheme,discount_amount)
                           VALUES(?,?,?,?,?,?,?,?,?)""",
                         (order_id,p['id'],qty,rate,round(rate*qty,2),p['flavor'] or '',mrp,'',0))
            conn.execute('UPDATE products SET stock=MAX(0,stock-?),updated_at=? WHERE id=?',(qty,now,p['id']))
            conn.execute('UPDATE depot_stock SET quantity=MAX(0,quantity-?),updated_at=? WHERE product_id=?',(qty,now,p['id']))
            conn.execute('UPDATE inventory SET available_quantity=MAX(0,available_quantity-?),updated_at=? WHERE product_id=?',(qty,now,p['id']))
        conn.commit(); flash(f'Secondary Order {ref} saved for {selected["dealer_name"]}.','success')
    except Exception as e:
        conn.rollback(); flash(str(e),'danger')
    finally:
        conn.close()
    dealer_id=request.form.get('dealer_id', type=int)
    return redirect(url_for('smr',dealer_id=dealer_id) if dealer_id else url_for('smr'))


@app.route('/smr/export')
def smr_export():
    if not login_required(): return redirect(url_for('login'))
    conn=db()
    try:
        dealers=_smr_mapped_dealers(conn); allowed={int(d['id']) for d in dealers}
        requested=request.args.get('dealer_id', type=int)
        dealer_id=requested if requested in allowed else (int(dealers[0]['id']) if dealers else None)
        dealer=conn.execute('SELECT * FROM dealers WHERE id=? AND active=1',(dealer_id,)).fetchone() if dealer_id else None
        rows=_smr_build_rows(conn,dealer_id)
        employee=conn.execute('SELECT * FROM users WHERE name=? OR user_code=? ORDER BY id LIMIT 1',
                              (dealer['emp_name'],dealer['emp_code'])).fetchone() if dealer else None
        wb=Workbook(); ws=wb.active; ws.title='SMR Stock Summary'
        ws.merge_cells('A1:H1'); ws['A1']='SMR - STOCK SUMMARY REPORT'
        ws['A1'].font=Font(size=16,bold=True,color='FFFFFF'); ws['A1'].fill=PatternFill('solid',fgColor='1F4E78'); ws['A1'].alignment=Alignment(horizontal='center')
        ws['A2']='Dealer'; ws['B2']=dealer['dealer_name'] if dealer else ''
        ws['D2']='Town'; ws['E2']=dealer['town'] if dealer else ''
        ws['A3']='Mapped Employee'; ws['B3']=employee['name'] if employee else (dealer['emp_name'] if dealer else '')
        ws['D3']='Generated On'; ws['E3']=datetime.now().strftime('%d-%b-%Y %I:%M %p')
        headers=['S.No','Category','Product Name','MRP (₹)','Opening Stock','Primary Order','Secondary Order','Closing Stock']
        for c,h in enumerate(headers,1):
            cell=ws.cell(5,c,h); cell.font=Font(bold=True,color='FFFFFF'); cell.fill=PatternFill('solid',fgColor='1F4E78'); cell.alignment=Alignment(horizontal='center')
        for i,r in enumerate(rows,1):
            for c,v in enumerate([i,r['category'],r['name'],r['mrp'],r['opening'],r['primary'],r['secondary'],r['closing']],1): ws.cell(5+i,c,v)
        total_row=6+len(rows); ws.cell(total_row,1,'TOTAL').font=Font(bold=True)
        for c in (5,6,7,8): ws.cell(total_row,c,f'=SUM({get_column_letter(c)}6:{get_column_letter(c)}{total_row-1})').font=Font(bold=True)
        for row in ws.iter_rows(min_row=5,max_row=total_row,min_col=1,max_col=8):
            for cell in row: cell.alignment=Alignment(horizontal='center',vertical='center')
        for cell in ws['D'][5:total_row]: cell.number_format='₹#,##0.00'
        for i,w in enumerate([8,24,42,12,16,16,18,16],1): ws.column_dimensions[get_column_letter(i)].width=w
        ws.freeze_panes='A6'; ws.auto_filter.ref=f'A5:H{total_row-1}'
        note_row=total_row+2; ws.cell(note_row,1,'Notes').font=Font(bold=True)
        ws.cell(note_row+1,1,'• All products from the supplied product catalogue are included, including zero-stock products.')
        ws.cell(note_row+2,1,'• Products are grouped by category. MRP is included in the downloaded Excel.')
        ws.cell(note_row+3,1,'• MRP editing in the application is restricted to Admin.')
        bio=io.BytesIO(); wb.save(bio); bio.seek(0)
        safe=(dealer['dealer_name'] if dealer else 'SMR').replace(' ','_').replace('/','_')
        return send_file(bio,as_attachment=True,download_name=f'SMR_Stock_Summary_{safe}.xlsx',mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    finally:
        conn.close()


def _flavors_for_product(conn, product):
    names=[]
    if product['flavor']:
        names=[x.strip() for x in str(product['flavor']).replace(';', ',').split(',') if x.strip()]
    if product['category']:
        for r in conn.execute("""SELECT f.name FROM flavors f JOIN categories c ON c.id=f.category_id WHERE c.name=? ORDER BY f.name""", (product['category'],)).fetchall():
            if r['name'] not in names: names.append(r['name'])
    return names

def _accessible_dealer(conn, dealer_id):
    if not dealer_id: return None
    d=conn.execute("SELECT * FROM dealers WHERE id=? AND active=1",(dealer_id,)).fetchone()
    if not d: return None
    if session.get('role') == 'ADMIN': return d
    u=conn.execute("SELECT user_code,name FROM users WHERE id=?",(session.get('user_id'),)).fetchone()
    if not u or (u['user_code'] and d['emp_code'] != u['user_code']): return None
    if not u['user_code'] and d['emp_name'] != u['name']: return None
    return d

def _build_primary_draft(conn, dealer_id, selected_ids, form):
    dealer=_accessible_dealer(conn,dealer_id)
    if not dealer: raise ValueError("Please select a valid Dealer first.")
    if not selected_ids: raise ValueError("Select at least one product.")
    items=[]
    for pid_text in selected_ids:
        pid=int(pid_text)
        p=conn.execute("SELECT * FROM products WHERE id=? AND status='ACTIVE'",(pid,)).fetchone()
        if not p: raise ValueError("One of the selected products was not found.")
        qty=int(form.get(f"quantity_{pid}", "0"))
        qty_min,qty_step=quantity_rule_for_product(p['category'],p['brand'],p['name'])
        if qty < qty_min or (qty-qty_min)%qty_step != 0:
            raise ValueError(f"Quantity for {p['name']} must be {qty_min}, {qty_min + qty_step}, {qty_min + 2*qty_step}... only.")
        mrp=float(p['mrp'] or p['price'] or 0)
        rate=float(p['price'] or 0)
        items.append({"product_id":pid,"product_name":p['name'],"product_code":p['product_code'],"brand":p['brand'],"category":p['category'],"flavor":"","mrp":mrp,"rate":rate,"quantity":qty,"case_size":p['case_size'] or 0})

    items, group_summaries=apply_overall_schemes(conn, items)
    return {"dealer_id":dealer['id'],"dealer_name":dealer['dealer_name'],"town":dealer['town'],"sap_code":dealer['sap_code'],"items":items,"scheme_groups":group_summaries}

@app.route("/products/save-selection", methods=["POST"])
def products_save_selection():
    if not login_required():
        return jsonify({"error": "Please log in to save your product selection."}), 401

    dealer_id=(request.form.get('dealer_id') or '').strip()
    items={}
    for product_id in request.form.getlist('selected_products'):
        try:
            product_id=str(int(product_id))
            quantity=int(request.form.get(f"quantity_{product_id}", "0"))
        except (TypeError, ValueError):
            return jsonify({"error": "Invalid product selection."}), 400
        if int(product_id) <= 0 or quantity <= 0:
            return jsonify({"error": "Invalid product selection."}), 400
        items[product_id]=quantity

    session['product_selection']={"dealer_id":dealer_id,"items":items}
    return jsonify({"ok": True})

