@app.route("/admin/inventory", methods=["GET","POST"])
def inventory():
    if not admin_required(): return redirect(url_for("admin_login"))
    conn=db()
    if request.method=="POST":
        product_id=int(request.form["product_id"]); available=max(0,int(request.form.get("available_quantity",0))); reserved=max(0,int(request.form.get("reserved_quantity",0))); reorder=max(0,int(request.form.get("reorder_level",10))); now=datetime.now().isoformat(timespec="seconds")
        conn.execute("INSERT INTO inventory(product_id,available_quantity,reserved_quantity,reorder_level,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(product_id) DO UPDATE SET available_quantity=excluded.available_quantity,reserved_quantity=excluded.reserved_quantity,reorder_level=excluded.reorder_level,updated_at=excluded.updated_at",(product_id,available,reserved,reorder,now)); conn.execute("UPDATE products SET stock=?,updated_at=? WHERE id=?",(available,now,product_id)); conn.commit(); flash("Inventory updated successfully.","success")
    rows=conn.execute("SELECT i.*,p.product_code,p.name FROM inventory i JOIN products p ON p.id=i.product_id ORDER BY p.name").fetchall(); products=conn.execute("SELECT id,name,product_code FROM products ORDER BY name").fetchall(); conn.close()
    return render_template("admin/inventory.html",rows=rows,products=products)

@app.route("/admin/scheme-adjustment", methods=["GET","POST"])
def scheme_adjustment():
    if not admin_required(): return redirect(url_for("admin_login"))
    conn=db(); seed_nv_scheme_rules(conn)
    if request.method=="POST":
        try:
            category_name=request.form.get("category_name","").strip()
            brand=request.form.get("brand","ENVY").strip() or "ENVY"
            allowed={r[0] for r in NV_SCHEME_CATEGORIES} | {r[0] for r in PURE_HOME_SCHEME_CATEGORIES}
            if category_name not in allowed:
                raise ValueError("Please select a valid brand category.")
            vals={
                "trade_promotion":float(request.form.get("trade_promotion",0) or 0),
                "slab1_percent":float(request.form.get("slab1_percent",0) or 0),
                "slab1_cs":float(request.form.get("slab1_cs",0) or 0),
                "slab2_percent":float(request.form.get("slab2_percent",0) or 0),
                "slab2_cs":float(request.form.get("slab2_cs",0) or 0),
                "slab3_percent":float(request.form.get("slab3_percent",0) or 0),
                "slab3_cs":float(request.form.get("slab3_cs",0) or 0),
            }
            if any(v<0 or v>100 for k,v in vals.items() if 'percent' in k or k=='trade_promotion'):
                raise ValueError("Percentage values must be between 0 and 100.")
            now=datetime.now().isoformat(timespec="seconds")
            ensure_scheme_columns(conn)
            conn.execute("""UPDATE nv_scheme_categories SET
                brand=?,trade_promotion=?,slab1_percent=?,slab1_cs=?,slab2_percent=?,slab2_cs=?,slab3_percent=?,slab3_cs=?,
                slab1_text=?,slab2_text=?,slab3_text=?,updated_at=? WHERE category_name=?""",
                (brand,vals["trade_promotion"],vals["slab1_percent"],vals["slab1_cs"],vals["slab2_percent"],vals["slab2_cs"],vals["slab3_percent"],vals["slab3_cs"],
                 f"{vals['slab1_percent']:g}% on {vals['slab1_cs']:g} CS" if vals['slab1_cs'] else '',
                 f"{vals['slab2_percent']:g}% on {vals['slab2_cs']:g} CS" if vals['slab2_cs'] else '',
                 f"{vals['slab3_percent']:g}% on {vals['slab3_cs']:g} CS" if vals['slab3_cs'] else '',now,category_name))
            conn.commit(); flash(f"{brand} category scheme updated successfully. Margin, MRP and Rate remain locked.","success")
        except (ValueError,sqlite3.Error) as e:
            conn.rollback(); flash(str(e),"danger")
    rows=conn.execute("""SELECT * FROM nv_scheme_categories ORDER BY CASE brand WHEN 'ENVY' THEN 0 WHEN 'Pure Home' THEN 1 ELSE 2 END, id""").fetchall()
    rows=[dict(r) for r in rows]
    conn.close(); return render_template("admin/scheme_adjustment.html",rows=rows,categories=rows)


