@app.route("/admin/user/toggle/<int:user_id>", methods=["POST"])
def toggle_user(user_id):
    if not admin_required():
        if request.is_json:
            return jsonify({"success": False, "message": "Administrator access is required."}), 403
        return redirect(url_for("admin_login"))

    conn = db()
    try:
        _ensure_user_activation_schema(conn)
        user = conn.execute("SELECT id, role, is_active FROM users WHERE id=?", (user_id,)).fetchone()
        if not user:
            message = "User not found."
            status_code = 404
            success = False
        elif int(user["id"]) == int(session.get("user_id", 0)):
            message = "You cannot deactivate your own account."
            status_code = 400
            success = False
            is_active = bool(user["is_active"])
        elif user["role"] == "ADMIN" and user["is_active"]:
            active_admins = conn.execute(
                "SELECT COUNT(*) AS count FROM users WHERE role='ADMIN' AND is_active=TRUE"
            ).fetchone()["count"]
            if active_admins <= 1:
                message = "At least one active admin account must remain."
                status_code = 400
                success = False
                is_active = True
            else:
                conn.execute(
                    "UPDATE users SET is_active=FALSE WHERE id=?",
                    (user_id,)
                )
                conn.commit()
                message = "User account deactivated."
                status_code = 200
                success = True
                is_active = False
        else:
            new_status = not bool(user["is_active"])
            conn.execute("UPDATE users SET is_active=? WHERE id=?", (new_status, user_id))
            conn.commit()
            message = "User account activated." if new_status else "User account deactivated."
            status_code = 200
            success = True
            is_active = new_status

        if request.is_json:
            return jsonify({"success": success, "is_active": is_active if user else None, "message": message}), status_code
        flash(message, "success" if success else "warning")
        return redirect(url_for("admin_users"))
    finally:
        conn.close()


@app.route("/admin/dealers", methods=["GET","POST"])
def admin_dealers():
    if not admin_required():
        return redirect(url_for("admin_login"))
    conn=db()
    try:
        _ensure_dealer_contact_schema(conn)
        if request.method=="POST":
            action=request.form.get("action","map").strip().lower()
            if action=="add_dealer":
                dealer_name=request.form.get("dealer_name","").strip()
                sap_code=request.form.get("sap_code","").strip()
                town=request.form.get("town","").strip()
                emp_name=request.form.get("emp_name","").strip()
                emp_code=request.form.get("emp_code","").strip()
                if not dealer_name or not sap_code or not town:
                    raise ValueError("Dealer Name, SAP Code and Town are required.")
                conn.execute("INSERT INTO dealers(dealer_name,sap_code,town,emp_name,emp_code,active) VALUES(?,?,?,?,?,1)",
                             (dealer_name,sap_code,town,emp_name,emp_code))
                conn.commit()
                flash(f"Dealer '{dealer_name}' added successfully.","success")
                return redirect(url_for("admin_dealers"))
            dealer_id=int(request.form["dealer_id"])
            emp_name=request.form.get("emp_name","").strip()
            emp_code=request.form.get("emp_code","").strip()
            conn.execute("UPDATE dealers SET emp_name=?, emp_code=? WHERE id=?",(emp_name,emp_code,dealer_id))
            conn.commit()
            flash("Dealer/User mapping updated.","success")
    except sqlite3.IntegrityError:
        conn.rollback(); flash("Dealer Name or SAP Code already exists.","danger")
    except Exception as e:
        conn.rollback(); flash(str(e),"danger")
    dealers=conn.execute("SELECT * FROM dealers ORDER BY dealer_name").fetchall()
    user_options=conn.execute("SELECT name,email FROM users WHERE role='USER' ORDER BY name").fetchall()
    conn.close()
    return render_template("admin/dealers.html",dealers=dealers,user_options=user_options)

@app.route("/admin/orders")
def admin_orders():
    if not admin_required(): return redirect(url_for("admin_login"))
    now = datetime.now()
    start_date=(request.args.get("start_date") or now.replace(day=1).strftime("%Y-%m-%d")).strip()
    end_date=(request.args.get("end_date") or now.strftime("%Y-%m-%d")).strip()
    legacy_date=(request.args.get("date") or "").strip()
    if legacy_date and not request.args.get("start_date") and not request.args.get("end_date"):
        start_date = legacy_date
        end_date = legacy_date
    try:
        datetime.strptime(start_date, "%Y-%m-%d")
        datetime.strptime(end_date, "%Y-%m-%d")
    except ValueError:
        start_date = now.replace(day=1).strftime("%Y-%m-%d")
        end_date = now.strftime("%Y-%m-%d")
    if start_date > end_date:
        start_date, end_date = end_date, start_date

    conn=db()
    orders=conn.execute("""
        SELECT o.*, u.name customer, u.email,
               d.dealer_name, d.town,
               COALESCE(o.order_type,'SALES ORDER') AS display_type,
               CASE WHEN o.status IN ('COMPLETED','PROCESSING','APPROVED','CONFIRMED') THEN 'CONFIRMED' WHEN o.status IN ('CANCELLED','REJECTED','CANCELED') THEN 'CANCELED' ELSE 'PENDING' END AS display_status,
               (SELECT string_agg(
                    p.name || ' × ' || oi.quantity ||
                    ' | MRP ₹' || to_char(COALESCE(oi.mrp,p.mrp,p.price), 'FM9999999990.00') ||
                    ' | Rate ₹' || to_char(oi.unit_price, 'FM9999999990.00') ||
                    ' | Scheme ' || COALESCE(oi.scheme,'0') || '%' ||
                    ' | Net ₹' || to_char(oi.unit_price, 'FM9999999990.00') ||
                    ' | Total ₹' || to_char(oi.total_price, 'FM9999999990.00'),
                    ' || '
                )
                FROM order_items oi JOIN products p ON p.id=oi.product_id
                WHERE oi.order_id=o.id) AS product_summary,
               (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) AS items_count,
               CASE WHEN NULLIF(CAST(o.billing_date AS TEXT),'') IS NOT NULL
                    THEN CAST(o.billing_date AS DATE)
                    ELSE CAST(o.order_date AS TIMESTAMP)::date END AS display_date
        FROM orders o
        JOIN users u ON u.id=o.user_id
        LEFT JOIN dealers d ON d.id=o.dealer_id
       WHERE (CASE WHEN NULLIF(CAST(o.billing_date AS TEXT),'') IS NOT NULL THEN CAST(o.billing_date AS DATE) ELSE CAST(o.order_date AS TIMESTAMP)::date END)
             BETWEEN ?::date AND ?::date
        ORDER BY o.id DESC
    """, (start_date, end_date)).fetchall()
    pending_orders_count = sum(1 for order in orders if order["display_status"] == "PENDING")
    conn.close()
    return render_template("admin/orders.html", orders=orders, selected_date=end_date,
                           start_date=start_date, end_date=end_date, pending_orders_count=pending_orders_count)

