@app.route("/admin/sales")
def admin_sales():
    access_response = _report_access_response()
    if access_response: return access_response
    conn=db()
    product_sales=conn.execute("""
        SELECT p.name, SUM(oi.quantity) qty, SUM(oi.total_price) sales
        FROM order_items oi JOIN products p ON p.id=oi.product_id
        JOIN orders o ON o.id=oi.order_id
        WHERE o.status IN ('CONFIRMED','COMPLETED')
        GROUP BY p.id ORDER BY sales DESC LIMIT 10
    """).fetchall()
    monthly=conn.execute("""
       SELECT TO_CHAR(CAST(order_date AS TIMESTAMP), 'YYYY-MM') AS month, SUM(total_amount) AS sales, COUNT(*) AS orders
FROM orders WHERE status IN ('CONFIRMED','COMPLETED')
GROUP BY 1 ORDER BY 1
    """).fetchall()
    conn.close()
    return render_template("admin/sales.html", product_sales=product_sales, monthly=monthly)

def build_report(year=None):
    conn=db()
    rows=conn.execute("""
        SELECT TO_CHAR(CAST(order_date AS TIMESTAMP), 'YYYY-MM') AS month,
       COALESCE(SUM(total_amount),0) AS sales,
       COUNT(*) AS orders
FROM orders
WHERE status IN ('CONFIRMED','COMPLETED')
  AND EXTRACT(YEAR FROM CAST(order_date AS TIMESTAMP)) = ?
GROUP BY 1
ORDER BY 1
    """,(str(year or datetime.now().year),)).fetchall()
    conn.close()
    wb=Workbook(); ws=wb.active; ws.title="Monthly Cumulative Sales"
    ws["A1"]="SMR Monthly Cumulative Sales Report"; ws["A1"].font=Font(size=16,bold=True)
    ws["A2"]="Year"; ws["B2"]=year or datetime.now().year
    ws["A3"]="Generated"; ws["B3"]=datetime.now().strftime("%d-%m-%Y %H:%M")
    headers=["S.No","Month","Monthly Sales (₹)","Cumulative Sales (₹)","Number of Orders"]
    for c,h in enumerate(headers,1):
        cell=ws.cell(5,c,h); cell.font=Font(bold=True,color="FFFFFF"); cell.fill=PatternFill("solid",fgColor="163A5F"); cell.alignment=Alignment(horizontal="center")
    cumulative=0
    for i,row in enumerate(rows,1):
        cumulative += row["sales"]
        vals=[i,row["month"],round(row["sales"],2),round(cumulative,2),row["orders"]]
        for c,v in enumerate(vals,1): ws.cell(5+i,c,v)
    total_row=6+len(rows)
    ws.cell(total_row,1,"TOTAL").font=Font(bold=True)
    ws.cell(total_row,3,round(cumulative,2)).font=Font(bold=True)
    for col in range(1,6): ws.column_dimensions[get_column_letter(col)].width=[10,16,22,24,20][col-1]
    out=os.path.join(REPORT_DIR,f"SMR_Monthly_Cumulative_Sales_{year or datetime.now().year}.xlsx")
    wb.save(out)
    return out

@app.route("/admin/reports", methods=["GET","POST"])
def admin_reports():
    access_response = _report_access_response()
    if access_response: return access_response
    year=int(request.values.get("year",datetime.now().year))
    conn=db()
    rows=conn.execute("""
        SELECT TO_CHAR(CAST(order_date AS TIMESTAMP), 'YYYY-MM') AS month,
       SUM(total_amount) AS sales,
       COUNT(*) AS orders
FROM orders
WHERE status IN ('CONFIRMED','COMPLETED')
  AND EXTRACT(YEAR FROM CAST(order_date AS TIMESTAMP)) = ?
GROUP BY 1
ORDER BY 1
    """,(str(year),)).fetchall()
    conn.close()
    cumulative=0; report=[]
    for r in rows:
        cumulative += r["sales"]; report.append({"month":r["month"],"sales":r["sales"],"cumulative":cumulative,"orders":r["orders"]})
    return render_template("admin/reports.html", report=report, year=year)

@app.route("/admin/reports/download")
def admin_report_download():
    access_response = _report_access_response()
